  cases: [{"name":"盘古山钨矿","county":"于都县","lon":115.435,"lat":25.657,"cat":"tungsten","tag":"地下巷道开采 · 百年老矿","desc":"赣州百年钨矿开采史的典型代表。地下巷道开采引发采空塌陷，尾矿中砷、镉、铅随雨水淋溶进入水系，属\"伤口外露明显、水土带毒\"的复合型损伤。"},{"name":"漂塘钨矿","county":"大余县","lon":114.4,"lat":25.517,"cat":"tungsten","tag":"崇义-大余成矿带核心","desc":"地处西华山矿田东侧，矿石中砷、镉、铅等伴生元素随尾矿淋溶进入水土系统，污染持久难降解。"},{"name":"黄沙钨矿（铁山垅）","county":"于都县","lon":115.3,"lat":25.733,"cat":"tungsten","tag":"标准化排土场","desc":"配套标准化排土场，地表扰动相对可控；采空区沉降隐患与尾矿重金属释放仍需长期监测。"},{"name":"石古前石灰岩矿","county":"信丰县","lon":114.89,"lat":25.463,"cat":"nonmetal","tag":"年产260万吨 · 露天台阶","desc":"大型水泥原料矿山。爆破开挖直接铲除植被，属\"物理型显性破坏\"，化学污染微弱，后遗症最轻。"},{"name":"富家地硅石矿","county":"兴国县","lon":115.7614,"lat":26.5408,"cat":"nonmetal","tag":"坡面开挖","desc":"坡面露天开挖，水土流失风险较高；石英理化性质稳定，化学后遗症轻微。"},{"name":"武当小河背石英矿","county":"龙南市","lon":114.676,"lat":24.562,"cat":"nonmetal","tag":"脉石英 · 表层开挖","desc":"山体表层直接开挖，扬尘与悬浮物为主要污染物，生态后遗症在三类矿种中最轻。"},{"name":"隆坪萤石矿","county":"兴国县","lon":115.254,"lat":26.3778,"cat":"nonmetal","tag":"氟化物隐患","desc":"萤石含氟，淋溶水可能携带氟化物渗入土壤和水体，需额外关注水质监测。"},{"name":"水尾山萤石矿","county":"全南县","lon":114.44,"lat":24.792,"cat":"nonmetal","tag":"资源量161.5万吨","desc":"连片露天采坑造成植被剥离与地形破碎，兼具物理破坏与氟化物污染风险。"},{"name":"足洞重稀土矿（701矿）","county":"龙南市","lon":114.905,"lat":24.821,"cat":"rare_earth","tag":"第一代 · 池浸","gen":1,"desc":"全坡面铲山，风化壳彻底剥离，每吨稀土损毁植被160~200 m²，形成标志性\"白色荒漠\"。池浸法现已全面取缔。"},{"name":"甲子背稀土矿","county":"定南县","lon":115.038,"lat":24.947,"cat":"rare_earth","tag":"第二代 · 堆浸","gen":2,"desc":"喷淋浸取回收率提升至45%~55%，但每吨稀土仍消耗硫酸铵7~10吨，矿区径流氨氮常年突破地表水Ⅴ类标准。"},{"name":"三丘田稀土矿","county":"定南县","lon":115.076,"lat":24.907,"cat":"rare_earth","tag":"第三代 · 原地浸矿","gen":3,"desc":"地表植被整体保留，但铵盐沿岩层裂隙扩散，闭矿12年后土壤氨氮仍达本底值12~40倍，属\"地表完好、内脏慢性中毒\"。"},{"name":"长坑尾稀土矿","county":"定南县","lon":115.058,"lat":24.932,"cat":"rare_earth","tag":"第三代 · 原地浸矿","gen":3,"desc":"单位稀土植被损毁降至约10 m²，但铵盐残留无法回收，地下水氨氮污染具备长期性和隐蔽性。"},{"name":"内头坑稀土矿","county":"定南县","lon":115.102,"lat":24.962,"cat":"rare_earth","tag":"第三代 · 原地浸矿","gen":3,"desc":"山地原地浸矿，土壤氨氮长期胁迫植被生长，生态修复周期显著拉长。"},{"name":"木子山稀土矿（上下营）","county":"定南县","lon":115.002,"lat":24.9496,"cat":"rare_earth","tag":"第四代 · 无铵绿色工艺","gen":4,"desc":"改用镁盐、有机酸等环保药剂，回收率82%~88%，植被损毁压缩至2~3 m²/t，废液100%闭环回收，外排水质达地表水Ⅲ类。"}],

